// Build the fixture `verify-section-math.mjs` checks its arithmetic against.
//
// That harness needs one REAL solved section: a profile of ground and water
// from the service, not a hand-written array, because the thing under test is
// whether `src/lib/section.ts` reads a real profile correctly. The fixture
// used to live in /tmp and was regenerated by hand, which meant it vanished
// and the harness became unrunnable. This writes it where the harness looks.
//
//   node scripts/make-section-fixture.mjs          # needs the service on :8000
//
// The line is chosen rather than hardcoded: `/sites` is asked for the banks
// worth defending under the 31 October 2013 flood, and the section is cut
// across the one with the deepest shortfall — the bank closest to being
// overtopped, which is the one with water on both the drawing and the sums.
// A dry section would exercise none of the levee arithmetic.
import { writeFileSync, mkdirSync } from "node:fs";

const SERVICE = process.env.FLOOD_SERVICE ?? "http://127.0.0.1:8000";
const BOX = { west: -97.82, south: 30.11, east: -97.69, north: 30.21 };
const NAME = "Onion Creek, Austin, Texas";
// 31 Oct 2013 at Onion Ck at US Hwy 183 (USGS 08159000): 135,000 cfs.
const Q_2013 = 3822.8;
const OUT = new URL("./fixtures/", import.meta.url).pathname;

async function post(path, body) {
  const r = await fetch(`${SERVICE}${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(900_000),
  });
  if (!r.ok) throw new Error(`${path} → HTTP ${r.status}: ${(await r.text()).slice(0, 300)}`);
  return r.json();
}

const forcing = {
  driver: "river", river_q_m3s: Q_2013, river_q_is_design: true,
  rain_mm_h: 50, storm_hours: 6,
};

console.log("finding the banks worth defending …");
const sites = await post("/sites", {
  ...BOX, name: NAME, dx: 40, run_hours: 18, max_sites: 6, shortfall_m: 2.0,
  ...forcing,
});
if (!sites.ok) throw new Error(`no sites: ${sites.reason}`);
const site = sites.sites.reduce((a, s) => (s.needs_m > a.needs_m ? s : a), sites.sites[0]);
console.log(`  ${sites.sites.length} banks; deepest shortfall is`
  + ` ${site.name ?? "an unnamed bank"} at ${site.needs_m.toFixed(2)} m`);

// Widened to ±900 m. The section `/sites` returns is ±400 m, which crosses
// the bank and stops: the tie-back arithmetic needs floodplain on both sides
// of the crest to have anything to tie into.
const mid = { lat: site.lat, lon: site.lon };
const wide = (p, k) => ({
  lat: mid.lat + (p.lat - mid.lat) * k,
  lon: mid.lon + (p.lon - mid.lon) * k,
});
console.log("cutting the section …");
const sec = await post("/section", {
  a: wide(site.line.a, 2.25), b: wide(site.line.b, 2.25),
  name: `Onion Creek · ${site.name ?? "bank"}`,
  samples: 160, dx: 40, run_hours: 18, ...forcing,
});
if (!sec.ok) throw new Error(`no section: ${sec.reason}`);

const wet = sec.profile.filter((q) => q.water_m !== null).length;
console.log(`  ${sec.length_m.toFixed(0)} m, ${sec.samples} samples,`
  + ` ${wet} wet, peak water ${sec.peak_water_m ?? "none"}`);
if (wet < 12) {
  throw new Error("the section is dry — nothing here exercises the levee "
    + "arithmetic. Pick a larger scenario or a different bank.");
}

mkdirSync(OUT, { recursive: true });
writeFileSync(`${OUT}section_onion_creek.json`, JSON.stringify(sec));
console.log(`→ ${OUT}section_onion_creek.json`);
